// scripts/verify-release.ts (deploy job)
const manifest = JSON.parse(readFileSync("release-manifest.json", "utf8"));
if (manifest.signature) {
  if (!signatureValid(KEY, canonicalManifest(manifest), manifest.signature)) fail("bad signature");
}
for (const file of readdirSync("dist")) {
  const digest = sha256Hex(readFileSync(join("dist", file)));
  if (manifest.digests[file] !== digest) fail(`${file}: digest mismatch`);
}
deploy();

release-manifest.json and dist/ are downloaded from the same artifact bucket.

Statement: "Someone who can write to the bucket but does not have the signing key cannot get a modified web.tar.gz deployed through this script."
